class Solution:
    def maxPalindromicSum(self, nums: List[int]) -> int:
        n = len(nums)
        pre = [0] * (n + 1)
        for i, x in enumerate(nums):
            pre[i + 1] = pre[i] + x
        ans = max(nums)
        def best(l, r):
            nonlocal ans
            while l > 0 and r < n - 1 and nums[l - 1] == nums[r + 1]:
                l -= 1
                r += 1
            ans = max(ans, pre[r + 1] - pre[l])
        for i in range(n):
            best(i, i)
            if i + 1 < n and nums[i] == nums[i + 1]:
                best(i, i + 1)
        return ans

