class Solution {
public:
    long long maxPalindromicSum(vector<int>& nums) {
        int n = nums.size();
        vector<long long> pre(n + 1, 0);
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
        long long ans = *max_element(nums.begin(), nums.end());
        auto best = [&](int l, int r) {
            while (l > 0 && r < n - 1 && nums[l - 1] == nums[r + 1]) { l--; r++; }
            ans = max(ans, pre[r + 1] - pre[l]);
        };
        for (int i = 0; i < n; i++) {
            best(i, i);
            if (i + 1 < n && nums[i] == nums[i + 1]) best(i, i + 1);
        }
        return ans;
    }
};

