class Solution {
    public long maxPalindromicSum(int[] nums) {
        int n = nums.length;
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
        long ans = 0;
        for (int x : nums) ans = Math.max(ans, x);
        for (int i = 0; i < n; i++) {
            ans = Math.max(ans, best(nums, pre, i, i));
            if (i + 1 < n && nums[i] == nums[i + 1])
                ans = Math.max(ans, best(nums, pre, i, i + 1));
        }
        return ans;
    }
    private long best(int[] nums, long[] pre, int l, int r) {
        while (l > 0 && r < nums.length - 1 && nums[l - 1] == nums[r + 1]) { l--; r++; }
        return pre[r + 1] - pre[l];
    }
}

